import {reports as reportModel} from '../../prototype/reports.js';
import {validateStored,readStorage,saveStorage,STORAGE_KEY} from '../../prototype/storage.js';
const results=[],assert=(value,message)=>{if(!value)throw Error(message);};
const reports=(data,options)=>reportModel(data,options,6);
const stable=v=>JSON.stringify(v,(_,x)=>x && !Array.isArray(x) && typeof x==='object'?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a.localeCompare(b))):x);
const eq=(a,b,m)=>assert(stable(a)===stable(b),`${m}: ${stable(a)} != ${stable(b)}`);
async function test(name,fn){try{await fn();results.push({name,status:'PASS'});}catch(e){results.push({name,status:'FAIL',error:e.stack});}if(name.startsWith('UI-03'))await capture(name.match(/DEMO-\d+/)[0]+'-after');}
async function capture(name){
  window.__capture={name};
  await new Promise((resolve,reject)=>{const started=Date.now(),timer=setInterval(()=>{if(!window.__capture){clearInterval(timer);resolve();}else if(Date.now()-started>10000){clearInterval(timer);reject(Error('Screenshot runner timeout'));}},30);});
}
const at=(h,day='05')=>`2026-10-${day}T${h}+07:00`;
function step(d,h,a,p={},u=3,id=1,day='05'){advance(d,at(h,day));return act(d,a,id,p,u);}
function rejected(d,a,id,p,u,status,code){const before=stable(d),projection=stable(projections(d));let error;try{act(d,a,id,p,u);}catch(e){error=e;}assert(error,'Expected rejection');eq(error.status,status,'Error status');if(code)eq(error.code,code,'Error code');eq(stable(d),before,'Source unchanged');eq(stable(projections(d)),projection,'Projection unchanged');}
const payload={create:{title:'Kiểm thử',description:'Mô tả',priority:'HIGH'},message:{content:'Phản hồi'},note:{content:'Nội bộ'},resolve:{resolution_summary:'Kết quả'},reject:{reason:'Chưa đạt'},review:{handling_plan:{unresolved_reason:'Nguyên nhân',next_action:'Hướng mới',needs_expert_input:false}}};
const fixtures=await (await fetch('../sla/sla-scenarios.json')).json();
let comparisons=0;
for(const row of fixtures)await test(row.scenario_id,()=>{
  assert(row.review_status==='verified','Fixture verified');
  const r=replay(row.created_at,row.policy_id,row.events.filter(e=>e.type!=='resolved_attempt'),row.as_of),actual={};
  for(const clock of ['first_response','resolution'])for(const key of ['due_at','consumed_seconds','remaining_seconds','status','warning_level'])actual[`expected_${clock}_${key}`]=r.sla[clock][key];
  for(const clock of ['first_response','resolution']){const key=`${clock}_sla_status_at_assignment`;actual['expected_'+key]=r.snapshot?.[key]??null;}
  Object.assign(actual,{expected_resolution_intervals:r.resolution_intervals,expected_ticket_state:r.state,expected_rejection_count:r.rejection_count,expected_open_review:r.open_review,resolution_result_final:r.resolution_result_final,expected_reviews:r.reviews.map(({review_key,requested_at,completed_at,wait_calendar_seconds,wait_overlap_seconds,breach_context})=>({review_key,requested_at,completed_at,wait_calendar_seconds,wait_overlap_seconds,breach_context}))});
  for(const [key,value] of Object.entries(actual)){comparisons++;eq(value,row[key],`${row.scenario_id} ${key}`);}
});
await test('Fixture rejected attempts through JS controller',()=>{
  const map={agent_assigned:'claim',agent_public_reply:'message',status_waiting:'waiting',customer_public_message:'message',internal_note:'note',resolved:'resolve',customer_reject:'reject',customer_confirm:'confirm',review_completed:'review'};
  for(const row of fixtures){
    const d={schema_version:1,scenario:'DEMO-01',variant:'monday',identity:1,clock:row.created_at,tickets:[],events:[]};act(d,'create',null,{...payload.create,priority:row.policy_id},1);
    const steps=[...row.events.map(e=>({...e,accepted:true})),...row.expected_rejected_actions.map(e=>({...e,seq:e.step_seq,accepted:false}))].sort((a,b)=>timestamp(a.at)-timestamp(b.at)||a.seq-b.seq);
    for(const e of steps){advance(d,e.at);if(e.accepted && e.type!=='resolved_attempt'){const a=map[e.type];act(d,a,1,payload[a]||{},['customer_public_message','customer_reject','customer_confirm'].includes(e.type)?1:e.type==='review_completed'?6:3);}else rejected(d,'resolve',1,payload.resolve,3,409,'REVIEW_REQUIRED');}
  }
});
