const doc=()=>iframe.contentDocument;
const change=async(selector,value)=>{const e=doc().querySelector(selector);assert(e,selector);e.value=value;e.dispatchEvent(new Event('change',{bubbles:true}));await wait();};
const click=async(selector)=>{const e=doc().querySelector(selector);assert(e && !e.disabled,selector+' available');e.click();await wait();};
const form=async(selector,values={})=>{const f=doc().querySelector(selector);assert(f,selector);for(const [k,v]of Object.entries(values))f.elements[k].value=v;f.requestSubmit();await wait();};
